import{j as e,b as s,B as n,Z as d,T as l,L as r,c as i}from"./index-SZVe2leL.js";import{S as c}from"./SEOHead-DJb2_usO.js";import{B as h}from"./Breadcrumb-B40VbJpw.js";import{C as m}from"./Card--QX-CWdK.js";import{C as u}from"./chart-no-axes-column-K6mKsu3z.js";import{C as p}from"./chevron-right-DPg2gnYj.js";const o=[{id:"getting-started",icon:s,title:"Getting Started",items:[{heading:"1. Create your account",body:"Go to /register, pick your role (Student or Parent), enter your class/grade, and choose your preferred language. The whole process takes under 60 seconds."},{heading:"2. Set your class and board",body:"After sign-up, select your class (1–12) and board (CBSE/NCERT). This customises your dashboard to show your exact syllabus and relevant content."},{heading:"3. Pick your language",body:"EduLearn supports English, Hindi, Punjabi, and Bhojpuri. You can choose a different language per subject — for example, English for Maths and Hindi for History."}]},{id:"videos",icon:s,title:"Watching Video Lessons",items:[{heading:"Finding a video",body:"Navigate to Learn → select your Subject → Chapter → Exercise → Question. Each exercise question has a dedicated video solution. Use the search bar to jump straight to a topic."},{heading:"Video languages",body:"Tap the language selector (top-right of the video player) to switch between available language versions of the same video."},{heading:"Offline access",body:"Premium users can download videos for offline watching on the mobile app. Downloads are managed in your Library tab."}]},{id:"ai-tutor",icon:n,title:"Using the AI Tutor",items:[{heading:"How to ask a question",body:"Tap 'Ask AI' from your dashboard or the AI Assistant page. Type your question in plain language — e.g. 'Explain why √2 is irrational' or 'Help me solve this trigonometry problem'."},{heading:"Follow-up questions",body:"The AI remembers context within a conversation. If the first explanation isn't clear, ask a follow-up: 'Can you explain that in simpler terms?' or 'Show me a worked example'."},{heading:"Question limits",body:"Free plan: 10 AI questions per day. Premium plan: unlimited questions. Your daily limit resets at midnight (Indian Standard Time)."}]},{id:"quizzes",icon:d,title:"Practice Quizzes",items:[{heading:"Chapter quizzes",body:"After watching a video, use the practice questions to test your understanding. Each question comes with the correct answer and a detailed explanation."},{heading:"Adaptive mode",body:"The AI identifies which topics you're struggling with and automatically serves more practice on those areas. Your accuracy per topic is shown in your Progress dashboard."},{heading:"Previous year papers",body:"Access CBSE Class 10 and 12 previous year papers (2013–2024) under the PYPs section. These are marked and timed."}]},{id:"leaderboard",icon:l,title:"Leaderboards & Battles",items:[{heading:"Earning XP points",body:"Earn XP by watching videos (5 XP/video), taking quizzes (10–25 XP per quiz), maintaining streaks (bonus XP daily), and completing chapters."},{heading:"Live battles",body:"Challenge another student to a 1v1 quiz battle or join a group battle under the Battle section. Both participants answer the same set of questions under a time limit."},{heading:"Streak freezes",body:"Missed a day? You can use a Streak Freeze (earned by reaching 100 XP) to protect your streak once per week."}]},{id:"analytics",icon:u,title:"Progress & Analytics",items:[{heading:"Weekly report",body:"Every Monday, you receive a Weekly Report showing: study time, quizzes completed, accuracy per subject, XP earned, and your position on the leaderboard."},{heading:"Parent monitoring",body:"Parents can view their linked child's weekly report, chapter progress, study time heatmap, and set daily limits from the Parent Dashboard."},{heading:"Certificates",body:"Complete all chapters in a subject module to earn a downloadable PDF certificate. Access earned certificates in your Profile → Certificates tab."}]}];functio